15	export class ApiError extends Error {
16	  readonly code: string;
17	  readonly status: number;
18	  readonly path: string;
19	  constructor(envelope: ApiErrorEnvelope, path: string) {
20	    super(envelope.error);
21	    this.name = "ApiError";
22	    this.code = envelope.code;
23	    this.status = envelope.status;
24	    this.path = path;
25	  }
26	}
