28	export type ApiAction =
29	  | "approve" | "reject" | "saveMemory" | "skipMemory"
30	  | "extract" | "chat" | "load";
31	
32	export function friendlyApiError(err: unknown, action?: ApiAction): { title: string; description?: string } {
33	  if (err instanceof ApiError) {
34	    if (err.code === "CONFLICT" && action === "saveMemory") {
35	      return {
36	        title: "Memory write blocked",
37	        description: "Vendor hasn't reported completion yet — we don't write memory until the job closes.",
38	      };
39	    }
40	    if (err.code === "CONFLICT") {
41	      return { title: "Action blocked", description: err.message };
42	    }
43	    if (err.code === "VALIDATION_ERROR") {
44	      return { title: "Invalid request", description: err.message };
45	    }
46	    if (err.code === "UNAUTHORIZED") {
47	      return { title: "Sign-in required", description: err.message };
48	    }
49	    if (err.code === "NOT_FOUND") {
50	      return { title: "Not found", description: err.message };
51	    }
52	    return { title: "Request failed", description: err.message };
53	  }
54	  if (err instanceof DOMException && err.name === "AbortError") {
55	    return { title: "Cancelled" };
56	  }
57	  return {
58	    title: "Unexpected error",
59	    description: err instanceof Error ? err.message : String(err),
60	  };
61	}
