63	type FetchInit = Omit<RequestInit, "body"> & {
64	  query?: Record<string, string | number | boolean | undefined | null>;
65	  body?: unknown;
66	};
67	
68	function buildUrl(path: string, query?: FetchInit["query"]): string {
69	  const url = new URL(path.startsWith("http") ? path : `${BASE}${path}`);
70	  if (query) {
71	    for (const [k, v] of Object.entries(query)) {
72	      if (v === undefined || v === null) continue;
73	      url.searchParams.set(k, String(v));
74	    }
75	  }
76	  return url.toString();
77	}
78	
79	async function request<T>(path: string, init: FetchInit = {}): Promise<T> {
80	  const { query, body, headers, ...rest } = init;
81	  const url = buildUrl(path, query);
82	
83	  const res = await fetch(url, {
84	    ...rest,
85	    headers: {
86	      "Accept": "application/json",
87	      ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
88	      ...headers,
89	    },
90	    body: body === undefined ? undefined : JSON.stringify(body),
91	  });
92	
93	  if (!res.ok) {
94	    let envelope: ApiErrorEnvelope = {
95	      error: res.statusText || "Request failed",
96	      code: "HTTP_ERROR",
97	      status: res.status,
98	    };
99	    try {
100	      const parsed = await res.json();
101	      if (parsed && typeof parsed === "object" && "error" in parsed) {
102	        envelope = {
103	          error: String((parsed as ApiErrorEnvelope).error ?? envelope.error),
104	          code: String((parsed as ApiErrorEnvelope).code ?? envelope.code),
105	          status: Number((parsed as ApiErrorEnvelope).status ?? res.status),
106	        };
107	      }
108	    } catch {
109	      /* non-JSON error body */
110	    }
111	    throw new ApiError(envelope, path);
112	  }
113	
114	  if (res.status === 204) return undefined as unknown as T;
115	  return res.json() as Promise<T>;
116	}
