331	export const chat = {
332	  /**
333	   * SSE streaming chat. POST /api/chat returns text/event-stream.
334	   * Frames are delimited by `\n\n`; each frame has `event:` and `data:` lines.
335	   */
336	  stream: async (
337	    payload: { message: string; propertyId?: string; scope?: ChatScope },
338	    handlers: ChatStreamHandlers
339	  ): Promise<void> => {
340	    const url = buildUrl("/api/chat");
341	    const res = await fetch(url, {
342	      method: "POST",
343	      headers: { "Content-Type": "application/json", "Accept": "text/event-stream" },
344	      body: JSON.stringify(payload),
345	      signal: handlers.signal,
346	    });
347	
348	    if (!res.ok || !res.body) {
349	      const env: ApiErrorEnvelope = {
350	        error: `Chat stream failed (${res.status})`,
351	        code: "HTTP_ERROR",
352	        status: res.status,
353	      };
354	      try {
355	        const parsed = await res.json();
356	        if (parsed && typeof parsed === "object" && "error" in parsed) {
357	          Object.assign(env, parsed);
358	        }
359	      } catch { /* ignore */ }
360	      throw new ApiError(env, "/api/chat");
361	    }
362	
363	    const reader = res.body.getReader();
364	    const decoder = new TextDecoder("utf-8");
365	    let buffer = "";
366	
367	    try {
368	      while (true) {
369	        const { value, done } = await reader.read();
370	        if (done) break;
371	        buffer += decoder.decode(value, { stream: true });
372	
373	        let sep: number;
374	        while ((sep = buffer.indexOf("\n\n")) !== -1) {
375	          const frame = buffer.slice(0, sep);
376	          buffer = buffer.slice(sep + 2);
377	          parseSseFrame(frame, handlers);
378	        }
379	      }
380	      if (buffer.trim().length > 0) parseSseFrame(buffer, handlers);
381	    } catch (err) {
382	      handlers.onError?.(err);
383	      throw err;
384	    }
385	  },
386	};
387	
388	function parseSseFrame(frame: string, handlers: ChatStreamHandlers): void {
389	  let event = "message";
390	  const dataLines: string[] = [];
391	  for (const line of frame.split("\n")) {
392	    if (line.startsWith("event:")) event = line.slice(6).trim();
393	    else if (line.startsWith("data:")) dataLines.push(line.slice(5).trim());
394	  }
395	  if (dataLines.length === 0) return;
396	  const raw = dataLines.join("\n");
397	  let parsed: any;
398	  try { parsed = JSON.parse(raw); } catch { parsed = { text: raw }; }
399	
400	  if (event === "delta") handlers.onDelta?.(parsed.text ?? "");
401	  else if (event === "done") handlers.onDone?.({
402	    messageId: parsed.messageId,
403	    appliedTo: parsed.appliedTo ?? [],
404	  });
405	  else if (event === "error") handlers.onError?.(parsed);
406	}
