1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useState } from "react";
6	import { useTheme } from "next-themes";
7	import { cn } from "@repo/ui/lib/utils";
8	import {
9	  ChevronDown, ChevronRight, LayoutDashboard, AlertTriangle, Building2,
10	  Users, Wrench, FileText, MessageSquareText, Sparkles, Home,
11	  PanelLeftClose, PanelLeftOpen, Sun, Moon, RotateCcw, Loader2,
12	} from "lucide-react";
13	import { api } from "@/lib/api";
14	import { subscribe } from "@/lib/bus";
15	import { useToastSafe } from "@/components/toaster";
16	import type { Property } from "@/lib/types";
17	
18	const PROP_TABS = [
19	  ["tickets",  "Tickets"],
20	  ["units",    "Units & Owners"],
21	  ["context",  "Context"],
22	  ["editor",   "Editor"],
23	  ["versions", "Versions"],
24	  ["sources",  "Sources"],
25	  ["policies", "Policies"],
26	  ["calls",    "Calls"],
27	] as const;
28	
29	export function Sidebar() {
30	  const pathname = usePathname();
31	  const [collapsed, setCollapsed] = useState(false);
32	  const [openProps, setOpenProps] = useState<Record<string, boolean>>({ p1: true });
33	  const [properties, setProperties] = useState<Property[]>([]);
34	  const { theme, setTheme } = useTheme();
35	  const [mounted, setMounted] = useState(false);
36	  useEffect(() => setMounted(true), []);
37	
38	  // Demo reset state
39	  const [showResetConfirm, setShowResetConfirm] = useState(false);
40	  const [resetting, setResetting] = useState(false);
41	  const toast = useToastSafe();
42	
43	  useEffect(() => {
44	    let cancelled = false;
45	    const refresh = () =>
46	      api.properties.list()
47	        .then((list) => { if (!cancelled) setProperties(list); })
48	        .catch(() => { /* silently leave list empty */ });
49	    refresh();
50	    const unsub = subscribe((event) => {
51	      if (event.kind === "context-bumped" || event.kind === "ticket-changed") refresh();
52	    });
53	    return () => { cancelled = true; unsub(); };
54	  }, []);
55	
56	  const activePropId = pathname.match(/^\/property\/([^/]+)/)?.[1] ?? null;
57	  const activeProp = activePropId ? properties.find((p) => p.id === activePropId) ?? null : null;
58	
59	  async function handleReset() {
60	    setShowResetConfirm(false);
61	    setResetting(true);
62	    try {
63	      await api.dev.reset();
64	      toast.push({
65	        title: "Demo zurückgesetzt",
66	        description: "Alle Tickets und Daten wurden auf den Demo-Ausgangszustand zurückgesetzt.",
67	        variant: "success",
68	      });
69	      // Hard-redirect to overview so all client state (sidebar counts,
70	      // cached queries) is fully wiped — avoids the router.refresh() race
71	      // condition where refresh fires against the current route, not /overview.
72	      window.location.href = "/overview";
73	    } catch (err) {
74	      toast.push({
75	        title: "Reset fehlgeschlagen",
76	        description: err instanceof Error ? err.message : "Unbekannter Fehler beim Zurücksetzen.",
77	        variant: "destructive",
78	      });
79	    } finally {
80	      setResetting(false);
81	    }
82	  }
83	
84	  return (
85	    <>
86	      <aside
87	        className={cn(
88	          "flex h-full shrink-0 flex-col border-r bg-background transition-all duration-200",
89	          collapsed ? "w-14" : "w-64"
90	        )}
91	      >
92	        {/* Header */}
93	        <div className="flex h-14 items-center justify-between border-b px-3">
94	          {!collapsed && (
95	            <div className="flex items-center gap-2 min-w-0">
96	              <div className="grid h-7 w-7 shrink-0 place-items-center rounded-md bg-foreground text-background">
97	                <Sparkles className="h-4 w-4" />
98	              </div>
99	              <div className="flex flex-col leading-tight min-w-0">
100	                <span className="text-sm font-semibold">Buena</span>
101	                <span className="text-[10px] uppercase tracking-wider text-muted-foreground">Context Engine</span>
102	              </div>
103	            </div>
104	          )}
105	          {collapsed && (
106	            <div className="mx-auto grid h-7 w-7 place-items-center rounded-md bg-foreground text-background">
107	              <Sparkles className="h-4 w-4" />
108	            </div>
109	          )}
110	          {!collapsed && (
111	            <button
112	              onClick={() => setCollapsed(true)}
113	              className="ml-2 rounded-md p-1 text-muted-foreground hover:bg-accent hover:text-foreground"
114	              title="Collapse sidebar"
115	            >
116	              <PanelLeftClose className="h-4 w-4" />
117	            </button>
118	          )}
119	        </div>
120	
121	        {/* Demo Mode Banner (visible when expanded) */}
122	        {!collapsed && (
123	          <div className="flex items-center gap-1.5 border-b bg-amber-500/10 px-3 py-1.5">
124	            <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500 animate-pulse" />
125	            <span className="text-[10px] font-semibold uppercase tracking-wider text-amber-600 dark:text-amber-400">
126	              Demo Mode
127	            </span>
128	          </div>
129	        )}
130	
131	        {/* Expand button when collapsed */}
132	        {collapsed && (
133	          <button
134	            onClick={() => setCollapsed(false)}
135	            className="mx-auto mt-3 rounded-md p-1.5 text-muted-foreground hover:bg-accent hover:text-foreground"
136	            title="Expand sidebar"
137	          >
138	            <PanelLeftOpen className="h-4 w-4" />
139	          </button>
140	        )}
141	
142	        {/* Collapsed demo mode dot */}
143	        {collapsed && (
144	          <div
145	            className="mx-auto mt-1 h-1.5 w-1.5 rounded-full bg-amber-500"
146	            title="Demo Mode"
147	          />
148	        )}
149	
150	        {/* Nav */}
151	        <nav className={cn("flex-1 overflow-y-auto p-2 text-sm", collapsed && "overflow-hidden")}>
152	          {!collapsed ? (
153	            <>
154	              <Zone label="Work">
155	                <Item href="/overview"    icon={LayoutDashboard} active={pathname === "/overview"}>Overview</Item>
156	                <Item href="/escalations" icon={AlertTriangle}   active={pathname === "/escalations"}>Escalations</Item>
157	              </Zone>
158	
159	              <Zone label="Properties">
160	                {properties.map((p) => {
161	                  const open = openProps[p.id];
162	                  const inThisProp = pathname.startsWith(`/property/${p.id}`);
163	                  return (
164	                    <div key={p.id}>
165	                      <button
166	                        onClick={() => setOpenProps((s) => ({ ...s, [p.id]: !s[p.id] }))}
167	                        className={cn(
168	                          "flex w-full items-center justify-between gap-2 rounded-md px-2 py-1.5 hover:bg-accent",
169	                          inThisProp && "bg-accent"
170	                        )}
171	                      >
172	                        <span className="flex items-center gap-2 truncate text-sm">
173	                          <Home className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
174	                          <span className="truncate">{p.name}</span>
175	                        </span>
176	                        <span className="flex shrink-0 items-center gap-1.5">
177	                          {p.openTickets > 0 && (
178	                            <span className="rounded-full bg-amber-500/20 px-1.5 text-[10px] font-medium text-amber-600 dark:text-amber-400">
179	                              {p.openTickets}
180	                            </span>
181	                          )}
182	                          {open ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}
183	                        </span>
184	                      </button>
